# -*- coding: utf-8 -*-
# Обновление системного промта kip8 до post-Task 315-330
# (ПЕРЕНОС ПАРТИИ Tasks 315-330 из kip8test@f9e1a3c одним инкрементом
#  SW kipia-v417→v418): бар из трёх равных частей + окна мероприятий
#  и норм (315), подсветка/фильтр дня столбца (316), 3 ряда кнопок и
#  тултип «данные от» (317), увольнение (318), попап-мелочь (319-325),
#  итоги-шторка: столбцы/«Ещё» (327), тумблер перекрёстной подсветки
#  (328), шеврон/бортик/ширина-по-столбцам/дни/зебра (329), шапка
#  сине-серая + мелкий шрифт описаний + чёрный текст окон в светлой
#  теме (330).
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-06 (post-Task 330: ПЕРЕНОС ПАРТИИ Tasks 315-330 из kip8test@f9e1a3c в боевой kip8 ОДНИМ инкрементом SW kipia-v417→v418 — заявки пользователя: Task 315 «…сделай чтобы бар над шахматкой состоял из трёх равных частей…окно всех мероприятий месяца…окно норм времени и праздников…»; Task 316 «наведение на дату в шапке — подсветка столбца, клик — фильтр окна мероприятий по дню»; Task 317 «"данные от" — в тултип "Обновить"; кнопки в 3 ряда ровно в высоту окон»; Task 318 «увольнение сотрудника — дата увольнения + в архив»; Tasks 319-325 — попап кодов/карточка/шапка/стрелки/день-часы/колонка ФИО по тексту/зебра и тонкие линии шторки итогов; Task 326 — BUGFIX вложенности DOM (не открывались разделы и карточки расходомеров — потерян закрывающий </div> #page-work-schedule в Task 323); Task 327 «итоги учёта: без строки Итого и столбца Всего; основные Явки/Часы/Переработка; доп. столбцы за кнопкой "Ещё"; заголовки в 2 строки; бордюрчик; вкладки Месяц/Год при открытии»; Task 328 «кнопка-тумблер перекрёстной подсветки слева от "Сформировать"; кнопки бара меньше; тултипы с окон и кнопок убрать; подсказка "Сформировать" в формате "Обновить"»; Task 329 «шторка: "Ещё" → шеврон на левом краю + бортик; ширина ровно по столбцам (узкие, заголовки в 2 строки); переработка в ДНЯХ; зебра колонки ФИО»; Task 330 «фон шапки темнее, сине-серый; шрифт описаний кодов маленький; в светлой теме весь текст окон бара — чёрный». ПЕРЕНОС: патч index.html 3950 строк (diff kip8test 894afab..f9e1a3c, git apply ЧИСТО; изоляционных строк в диффе 0); sw.js kipia-v417→v418; СЕРВЕРНАЯ ЧАСТЬ партии — scripts/Code.gs (+5: case workSchedule.dismissEmployee) и scripts/WorkSchedule.gs (+336: dismissEmployee и пр.) — Apps Script развёртывание УЖЕ выполнено в сессиях kip8test (бэкенд общий для kip8/kip8test: WEB_APP_URL один), в kip8 синхронизированы ФАЙЛЫ .gs; tests/ — ВСЕ 48 файлов из kip8test с адаптацией версий (v569→v418 текущая, v570→v419 сторож, исторические v5XX→v417) + run-all.js; Тесты: 1584 → 2010/0 (ПАРИТЕТ с kip8test@f9e1a3c); 4 script-блока node --check OK. Верификация браузером на РЕАЛЬНОМ kip8/index.html: task315 33/33, task316 28/28, task317 49/49, task318 45/45 и task319 48/48 (скрипты актуализированы под Task 330), task320 24/24, task327 30/30, task328 36/36, task329 43/43, task330 27/27 + регресс task312 31/31, task313 30/30, task314 36/36 (13 скриптов, 420 проверок; 321-325 — устаревшие ДО Task 329, падают одинаково в kip8test/kip8, superseded 327/329). Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2 (SW v418); Apps Script/листы НЕ трогать (сервер уже развёрнут); kip8-desktop — автосинк.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
print('Строка 3 вставлена (цепочка версий)')

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-v417`',
     '> **Текущая версия кэша:** `kipia-v418`'),
    ('| `kip8` | PWA + APK | `kipia-v417` |',
     '| `kip8` | PWA + APK | `kipia-v418` |'),
    ('| `kip8test` | PWA | `kipia-test-v553` |',
     '| `kip8test` | PWA | `kipia-test-v569` |'),
    ('`CACHE_VERSION` (например, `kipia-v417`)',
     '`CACHE_VERSION` (например, `kipia-v418`)'),
    ('весь код в одном `index.html` (~40.5 тыс. строк, ~2.4 MB)',
     'весь код в одном `index.html` (~44.2 тыс. строк, ~2.6 MB)'),
    ('| Тесты | Node.js + кастомный фреймворк (`tests/`, 1584 теста, 32 тест-файла, `node tests/run-all.js`) |',
     '| Тесты | Node.js + кастомный фреймворк (`tests/`, 2010 тестов, 48 тест-файлов, `node tests/run-all.js`) |'),
    ('├── tests/                      # 1476 юнит-теста (Node.js, 27 файлов): run-all.js, test-role-access.js, и др.',
     '├── tests/                      # 2010 юнит-тестов (Node.js, 48 файлов): run-all.js, test-role-access.js, и др.'),
    ('ожидается `1433 passed, 0 failed`', 'ожидается `2010 passed, 0 failed`'),
    ('# Ожидается: 1433 passed, 0 failed', '# Ожидается: 2010 passed, 0 failed'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии/счётчики обновлены (%d замен)' % len(reps))

# «Последняя принятая партия» — строка целиком (732 до вставки): меняем
# заголовок и хвост
i = src.find('> **Последняя принятая партия:**')
j = src.find('\n', i)
assert i != -1 and j != -1
new_party = ('> **Последняя принятая партия:** Tasks 298-330 (коды Т-12/Т-13, мероприятия, одна кнопка «Сформировать», '
             'бар из ТРЁХ равных частей с окнами мероприятий/норм и 3 рядами кнопок, подсветка/фильтр дня столбца, '
             'увольнение в архив, попап кодов с переносом, шторка «Итоги учёта» — столбцы Явки/Часы/Переработка + '
             'доп. за ШЕВРОНОМ на левом краю (бортик, ширина РОВНО по столбцам, переработка в ДНЯХ, зебра ФИО), '
             'тумблер перекрёстной подсветки, шапка сине-серая #1e293b/#bfcad5 + мелкий шрифт описаний кодов + '
             'чёрный текст окон бара в светлой теме, локальная копия графика + «Обновить») — партия 315-330 из '
             'kip8test@f9e1a3c, kipia-v418, паритет тестов 2010/0 (Task 315-330-перенос, 2026-09-06; Apps Script '
             'уже развёрнут — файлы .gs синхронизированы в репо; листы не трогать).')
src = src[:i] + new_party + src[j:]
print('Строка «Последняя принятая партия» заменена')

# Буллет переноса в журнал переносов (после «Перенос Task 312+313+314 …»)
entry = ('- **Перенос Tasks 315-330 (партия, kip8test@f9e1a3c → kip8, один инкремент SW kipia-v417→v418):** '
         '1) бар над шахматкой — ТРИ равные части: колонка кнопок (3 ряда по 29,7px = 95px), окно ВСЕХ мероприятий месяца (центр), окно норм/праздников (право); «Отменить» в режиме правки; тултип «данные от» у «Обновить»; '
         '2) наведение/клик на дату шапки — подсветка столбца + фильтр мероприятий по дню (тоггл, Esc, сброс); '
         '3) увольнение: строка «Уволить…» в карточке + шторка (дата_увольнения H + в_архиве=1 I; сервер workSchedule.dismissEmployee — Apps Script УЖЕ развёрнут, .gs синхронизированы в kip8); '
         '4) шторка «Итоги учёта»: Явки/Часы/Переработка + доп. столбцы за ШЕВРОНОМ #wsTtChv на левом краю (середина высоты), бортик 5px, ширина РОВНО по столбцам (узкие по заголовкам в 2 строки), ПЕРЕРАБОТКА В ДНЯХ (часы в тултипе), зебра колонки ФИО; '
         '5) кнопка-тумблер перекрёстной подсветки (слева от «Сформировать», localStorage), кнопки бара меньше, тултипы убраны, подсказка «Сформировать» в формате «Обновить»; '
         '6) BUGFIX Task 326: восстановлен закрывающий </div> #page-work-schedule (не открывались разделы и карточки расходомеров); '
         '7) шапка шахматки — сине-серая #1e293b (тёмная) / #bfcad5 (светлая, темнее), hover «Сотрудник +» #2a3a4c; попап кодов — описания 10px; светлая тема — ВЕСЬ текст окон «Мероприятия»/«Норма» чёрный (подложки цветные). '
         'Верификация: патч index.html 3950 строк чисто (изоляция 0 строк), тесты 1584→2010/0 (паритет), браузер на kip8: 315=33/33, 316=28/28, 317=49/49, 318=45/45, 319=48/48, 320=24/24, 327=30/30, 328=36/36, 329=43/43, 330=27/27 + регресс 312=31/31, 313=30/30, 314=36/36 (321-325 устарели до 329 — superseded 327/329). '
         'Деплой: GitHub Pages + Ctrl+Shift+R ×1–2 (SW v418); Apps Script/листы НЕ трогать (сервер уже развёрнут с сессий kip8test); kip8-desktop — автосинк. См. scripts/DEPLOY-Task315-330-batch-transfer.md')
anchor = '- **Перенос Task 312+313+314 (партия, kip8t'
i = src.find(anchor)
assert i != -1, 'якорь журнала переносов не найден'
j = src.find('\n', i)
src = src[:j+1] + entry + '\n' + src[j+1:]
print('Буллет переноса добавлен в журнал')

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Промт kip8 обновлён до post-Task 315-330 (перенос партии)')
